def exe_name():
    return os.path.basename(sys.argv[0]) or "executable"


def eprint(s=""):
    sys.stderr.write(s + "\n")


def usage_for(context=None):
    name = exe_name()
    if context in ("--help", "--version"):
        return f"Usage: {name} {context} [ROOT]"
    if context in VALUE_OPTS:
        return f"Usage: {name} {context} {VALUE_OPTS[context]} [ROOT]"
    return f"Usage: {name} [OPTIONS] [ROOT]"


def die_unexpected(arg, context=None):
    eprint(f"error: unexpected argument '{arg}' found")
    if arg.startswith('-'):
        eprint("")
        eprint(f"  tip: to pass '{arg}' as a value, use '-- {arg}'")
    eprint("")
    eprint(usage_for(context))
    sys.exit(2)


def die_missing(opt):
    metavar = VALUE_OPTS[opt]
    eprint(f"error: a value is required for '{opt} {metavar}' but none was supplied")
    if opt in ENUMS:
        eprint(f"  [possible values: {', '.join(ENUMS[opt])}]")
    sys.exit(2)


def die_invalid_enum(opt, val):
    metavar = VALUE_OPTS[opt]
    eprint(f"error: invalid value '{val}' for '{opt} {metavar}'")
    eprint(f"  [possible values: {', '.join(ENUMS[opt])}]")
    sys.exit(2)


def rust_int_error(val):
    if val == "":
        return "cannot parse integer from empty string"
    return "invalid digit found in string"


def die_invalid_int(opt, val):
    metavar = VALUE_OPTS[opt]
    eprint(f"error: invalid value '{val}' for '{opt} {metavar}': {rust_int_error(val)}")
    sys.exit(2)


def opt_context(opts):
    for o in ("--help", "--version", "--print-shell-function", "--write-default-conf"):
        if o in opts:
            return o
    for o in LONG_FLAGS:
        if o in opts:
            return o
    return None


def parse_args(argv):
    opts = {}
    root = None
    i = 0
    after_dashdash = False
    context = None
    while i < len(argv):
        arg = argv[i]
        if after_dashdash:
            if root is None:
                root = arg
            else:
                die_unexpected(arg, context)
            i += 1
            continue
        if arg == "--":
            after_dashdash = True
            i += 1
            continue
        if arg.startswith("--") and arg != "--":
            if "=" in arg:
                opt, val = arg.split("=", 1)
                had_equal = True
            else:
                opt, val, had_equal = arg, None, False
            if opt in LONG_FLAGS:
                if had_equal:
                    eprint(f"error: unexpected value '{val}' for '{opt}' found; no more were expected")
                    eprint("")
                    eprint(usage_for(opt))
                    sys.exit(2)
                opts[opt] = True
                if context is None:
                    context = opt
                i += 1
                continue
            if opt in VALUE_OPTS:
                if not had_equal:
                    if i + 1 >= len(argv):
                        die_missing(opt)
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        die_unexpected(nxt, context)
                    val = nxt
                    i += 2
                else:
                    i += 1
                if opt in ENUMS:
                    if val == "":
                        die_missing(opt)
                    if val not in ENUMS[opt]:
                        die_invalid_enum(opt, val)
                if opt in INT_OPTS:
                    if not (val.startswith('+') and val[1:].isdigit() or val.isdigit()):
                        die_invalid_int(opt, val)
                opts[opt] = val
                if context is None:
                    context = opt
                continue
            die_unexpected(arg, context)
        elif arg.startswith('-') and arg != "-":
            j = 1
            if len(arg) == 2 and arg[1] in SHORT_VALUE:
                opt = SHORT_VALUE[arg[1]]
                if i + 1 >= len(argv):
                    die_missing(opt)
                nxt = argv[i+1]
                if nxt.startswith('-'):
                    die_unexpected(nxt, context)
                opts[opt] = nxt
                if context is None:
                    context = opt
                i += 2
                continue
            while j < len(arg):
                c = arg[j]
                if c in SHORT_VALUE:
                    opt = SHORT_VALUE[c]
                    val = arg[j+1:]
                    if val.startswith('='):
                        val = val[1:]
                    if val == "":
                        if i + 1 >= len(argv):
                            die_missing(opt)
                        nxt = argv[i+1]
                        if nxt.startswith('-'):
                            die_unexpected(nxt, context)
                        val = nxt
                        i += 1
                    opts[opt] = val
                    if context is None:
                        context = opt
                    break
                elif c in SHORT_FLAGS:
                    long = {
                        'd':'--dates','D':'--no-dates','f':'--only-folders','F':'--no-only-folders',
                        'g':'--show-git-info','G':'--no-show-git-info','h':'--hidden','H':'--no-hidden',
                        'i':'--git-ignored','I':'--no-git-ignored','p':'--permissions','P':'--no-permissions',
                        's':'--sizes','S':'--no-sizes','w':'--whale-spotting','W':'--no-whale-spotting',
                        't':'--trim-root','T':'--no-trim-root'
                    }[c]
                    opts[long] = True
                    if context is None:
                        context = long
                    j += 1
                else:
                    die_unexpected('-' + c if len(arg)==2 else arg, context)
            i += 1
        else:
            if root is None:
                root = arg
                i += 1
            else:
                die_unexpected(arg, context)
    return opts, root


def project_root():
    # executable is normally in workspace root, source in src. Try cwd first, then file parents.
    here = Path(__file__).resolve()
    for p in [Path.cwd(), here.parent.parent, here.parent]:
        if (p / "resources" / "default-conf").exists():
            return p
    return Path.cwd()


def default_conf_dir():
    if os.environ.get("BROOT_CONFIG_DIR"):
        return Path(os.environ["BROOT_CONFIG_DIR"])
    return Path(os.environ.get("HOME", str(Path.home()))) / ".config" / "broot"


def copy_defaults(dst):
    dst = Path(dst)
    if dst.exists() and not dst.is_dir():
        eprint(f'IO Error : "{dst}" isn\'t a directory')
        sys.exit(1)
    try:
        dst.mkdir(parents=True, exist_ok=True)
        src = project_root() / "resources" / "default-conf"
        for item in src.rglob("*"):
            rel = item.relative_to(src)
            target = dst / rel
            if item.is_dir():
                target.mkdir(parents=True, exist_ok=True)
            else:
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(item, target)
    except OSError as ex:
        eprint(f"IO Error : {ex.strerror} (os error {ex.errno})")
        sys.exit(1)


def ensure_default_conf():
    d = default_conf_dir()
    if not (d / "conf.hjson").exists() or not (d / "verbs.hjson").exists():
        copy_defaults(d)
        sys.stdout.write(f'New Configuration files written in \x1b[1m"{d}"\x1b[0m.\n')
        sys.stdout.write("You should have a look at them: their comments will help you configure broot.\n")
        sys.stdout.write("You should especially set up your favourite editor in verbs.hjson.\n")


