    ldir = launcher_dir()
    inst = ldir / "installed-v4"
    ref = ldir / "refused"
    ldir.mkdir(parents=True, exist_ok=True)
    if state == "undefined":
        for p in [inst, ref]:
            if p.exists():
                sys.stdout.write(f"Removing \x1b[48;5;234m\x1b[38;5;250m{p}\x1b[49m\x1b[39m.\n")
                p.unlink()
        return
