        if ref.exists():
            sys.stdout.write(f"Removing \x1b[48;5;234m\x1b[38;5;250m{ref}\x1b[49m\x1b[39m.\n")
            ref.unlink()
        inst.write_text(INSTALLED_TEXT)
    elif state == "refused":
        if inst.exists():
            sys.stdout.write(f"Removing \x1b[48;5;234m\x1b[38;5;250m{inst}\x1b[49m\x1b[39m.\n")
            inst.unlink()
        ref.write_text(REFUSED_TEXT)


def print_shell(shell):
    if shell in ("bash", "zsh"):
        sys.stdout.write(BASH_ZSH_FUNC)
    elif shell == "fish":
        sys.stdout.write(FISH_FUNC)
    elif shell == "nushell":
        sys.stdout.write(NUSHELL_FUNC)
    elif shell == "powershell":
        sys.stdout.write(POWERSHELL_FUNC)
    else:
        eprint(f"Unknown shell: {shell}")
        sys.exit(1)


