def install_shell_function(clean=False):
    shell = Path(os.environ.get("SHELL", "/bin/bash")).name or "bash"
    if shell not in ("bash", "zsh", "fish", "nushell", "powershell"):
        shell = "bash"
    if clean:
        sys.stdout.write("You requested a clean (re)install.\n")
    conf_launcher = launcher_dir() / shell
    conf_launcher.mkdir(parents=True, exist_ok=True)
    share_launcher = data_home() / "broot" / "launcher" / shell
    share_launcher.mkdir(parents=True, exist_ok=True)
    script_path = share_launcher / "1"
    script = BASH_ZSH_FUNC if shell in ("bash", "zsh") else (FISH_FUNC if shell == "fish" else NUSHELL_FUNC)
    script_path.write_text(script)
    link_path = conf_launcher / "br"
    if link_path.exists() or link_path.is_symlink():
        link_path.unlink()
    try:
        link_path.symlink_to(script_path)
    except Exception:
        shutil.copyfile(script_path, link_path)
    sys.stdout.write(f"Writing \x1b[38;5;13m\x1b[3mbr\x1b[0m shell function in \x1b[48;5;234m\x1b[38;5;250m{script_path}\x1b[49m\x1b[39m.\n")
    sys.stdout.write(f"Creating link from \x1b[48;5;234m\x1b[38;5;250m{link_path}\x1b[49m\x1b[39m to \x1b[48;5;234m\x1b[38;5;250m{script_path}\x1b[49m\x1b[39m.\n")
    home = Path(os.environ.get("HOME", str(Path.home())))
    for rc, msg in [(home/".bashrc", "source"), (home/".zshrc", "exec zsh")]:
        if rc.exists():
            line = f"\nsource {link_path}\n"
            old = rc.read_text(errors="ignore")
            if str(link_path) not in old:
