def data_home():
    if os.environ.get("XDG_DATA_HOME"):
        return Path(os.environ["XDG_DATA_HOME"])
    return Path(os.environ.get("HOME", str(Path.home()))) / ".local" / "share"


def install_shell_function(clean=False):
    shell = Path(os.environ.get("SHELL", "/bin/bash")).name or "bash"
    if shell not in ("bash", "zsh", "fish", "nushell", "powershell"):
        shell = "bash"
    if clean:
        sys.stdout.write("You requested a clean (re)install.\n")
    conf_launcher = launcher_dir() / shell
    conf_launcher.mkdir(parents=True, exist_ok=True)
    share_launcher = data_home() / "broot" / "launcher" / shell
    share_launcher.mkdir(parents=True, exist_ok=True)
    script_path = share_launcher / "1"
    script = BASH_ZSH_FUNC if shell in ("bash", "zsh") else (FISH_FUNC if shell == "fish" else NUSHELL_FUNC)
    script_path.write_text(script)
    link_path = conf_launcher / "br"
    if link_path.exists() or link_path.is_symlink():
        link_path.unlink()
    try:
        link_path.symlink_to(script_path)
    except Exception:
        shutil.copyfile(script_path, link_path)
    sys.stdout.write(f"Writing \x1b[38;5;13m\x1b[3mbr\x1b[0m shell function in \x1b[48;5;234m\x1b[38;5;250m{script_path}\x1b[49m\x1b[39m.\n")
    sys.stdout.write(f"Creating link from \x1b[48;5;234m\x1b[38;5;250m{link_path}\x1b[49m\x1b[39m to \x1b[48;5;234m\x1b[38;5;250m{script_path}\x1b[49m\x1b[39m.\n")
    home = Path(os.environ.get("HOME", str(Path.home())))
    for rc, msg in [(home/".bashrc", "source"), (home/".zshrc", "exec zsh")]:
        if rc.exists():
            line = f"\nsource {link_path}\n"
            old = rc.read_text(errors="ignore")
            if str(link_path) not in old:
                with rc.open("a") as f: f.write(line)
            if msg == "source":
                sys.stdout.write(f"\x1b[48;5;234m\x1b[38;5;250m{rc}\x1b[49m\x1b[39m successfully patched, you can make the function immediately available with \x1b[48;5;234m\x1b[38;5;250msource \x1b[49m\x1b[39m\x1b[48;5;234m\x1b[38;5;250m{rc}\x1b[49m\x1b[39m\n")
            else:
                sys.stdout.write(f"\x1b[48;5;234m\x1b[38;5;250m{rc}\x1b[49m\x1b[39m successfully patched, you can make the function immediately available with \x1b[48;5;234m\x1b[38;5;250mexec zsh\x1b[49m\x1b[39m\n")
    set_install_state("installed")
    sys.stdout.write("\nThe \x1b[1mbr\x1b[0m function has been successfully installed.\n")
    sys.stdout.write("You may have to restart your shell or source your \n")
    sys.stdout.write("shell init files.\n")
    sys.stdout.write("Afterwards, you should start broot with \x1b[48;5;234m\x1b[38;5;250mbr\x1b[49m\x1b[39m in \n")
    sys.stdout.write("order to use its full power.\n")


def maybe_prompt_install():
    if os.environ.get("BR_INSTALL") == "no":
        return False
    ldir = launcher_dir()
    if (ldir / "installed-v4").exists() or (ldir / "refused").exists():
        return False
    sys.stdout.write("\n\x1b[1mBroot\x1b[0m should be launched using a shell function.\n")
    sys.stdout.write("This function most notably makes it possible to \x1b[48;5;234m\x1b[38;5;250mcd\x1b[49m\x1b[39m\n")
    sys.stdout.write("from inside broot\n")
    sys.stdout.write("(see \x1b[38;5;13m\x1b[3mhttps://dystroy.org/broot/install-br/\x1b[0m for \n")
    sys.stdout.write("explanations).\n\n")
    sys.stdout.write("Can I install it now? [\x1b[1mY\x1b[0m/n]\n")
    install_shell_function(False)
