    sys.exit(1)


def abs_root(root):
    if root is None:
        return str(Path.cwd())
    return str(Path(root).expanduser().resolve())


def simple_tree(root, show_hidden=False, max_lines=200):
    p = Path(root or ".").expanduser()
    if not p.exists():
        eprint("IO Error : No such file or directory (os error 2)")
        sys.exit(1)
    if p.is_file():
        p = p.parent
    lines = [str(p.resolve())]
    try:
        entries = sorted(p.iterdir(), key=lambda x: (not x.is_dir(), x.name.lower()))
    except Exception:
        entries = []
    if not show_hidden:
        entries = [e for e in entries if not e.name.startswith('.')]
    for idx, e in enumerate(entries[:max_lines]):
        branch = "└──" if idx == len(entries[:max_lines])-1 else "├──"
        name = e.name
        if e.is_symlink():
            try: name += " -> " + os.readlink(e)
            except OSError: name += " -> "
        lines.append(branch + name)
    return "\n".join(lines) + "\n"


def run_ui(opts, root):
    ensure_default_conf()
    if maybe_prompt_install():
        return 0
    path = Path(root or ".").expanduser()
    if root is not None and not path.exists():
        eprint("IO Error : No such file or directory (os error 2)")
        return 1
    cmd = opts.get("--cmd", "")
    if opts.get("--outcmd"):
        try:
            Path(opts["--outcmd"]).write_text("")
        except Exception:
            pass
    if opts.get("--send"):
        send_to_socket(opts["--send"])
    # The real TUI needs a controlling tty; without one it switches screen then reports a Termimad error.
    if not (sys.stdin.isatty() and sys.stderr.isatty()):
        sys.stderr.write("\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h")
        sys.stderr.write("\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h\x1b[?1049l")
        eprint("Termimad Error : IO error: No such device or address (os error 6)")
        return 1
    root_abs = abs_root(root)
    sep = os.environ.get("BROOT_CMD_SEPARATOR", ";")
    commands = [c.strip() for c in cmd.split(sep)] if cmd else []
    show_hidden = bool(opts.get("--hidden") or opts.get("--whale-spotting") or opts.get("--git-status"))
    for c in commands:
        if c in (":pp", ":print_path"):
            sys.stdout.write(root_abs + "\n")
            return 0
        if c in (":pt", ":print_tree"):
            sys.stdout.write(simple_tree(root_abs, show_hidden))
            return 0
        if c in (":q", ":quit"):
            return 0
        if c in (":cd", ":cdup") and opts.get("--outcmd"):
            Path(opts["--outcmd"]).write_text("cd " + root_abs)
            return 0
    sys.stdout.write(simple_tree(root_abs, show_hidden))
    return 0


def main():
    opts, root = parse_args(sys.argv[1:])
    if opts.get("--help"):
        print_help()
        return 0
    # parser validation complete; now execute special actions in the observed order
    if opts.get("--version"):
        sys.stdout.write(f"broot {VERSION}\n")
    if opts.get("--write-default-conf") is not None:
        copy_defaults(opts["--write-default-conf"])
    if opts.get("--set-install-state") is not None:
        set_install_state(opts["--set-install-state"])
    if opts.get("--print-shell-function") is not None:
        print_shell(opts["--print-shell-function"])
    if opts.get("--version") or opts.get("--write-default-conf") is not None or opts.get("--set-install-state") is not None or opts.get("--print-shell-function") is not None:
        return 0
    if opts.get("--install"):
        install_shell_function(True)
        return 0
    return run_ui(opts, root)

if __name__ == "__main__":
    try:
        sys.exit(main())
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(1)
